import{z as i,x as d,o,c as B,q as s,j as l,D as E,d as r,s as n,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"写时复制","description":"","frontmatter":{"title":"写时复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cow-fork.md","filePath":"cs/cow-fork.md","lastUpdated":1791063341000}'),p={name:"cs/cow-fork.md"};function c(C,a,m,f,h,D){const t=d("Mermaid");return o(),B("div",null,[a[2]||(a[2]=s('<h1 id="写时复制" tabindex="-1">写时复制 <a class="header-anchor" href="#写时复制" aria-label="Permalink to &quot;写时复制&quot;">​</a></h1><div class="epigraph"><p>fork 之后父子共享物理页并标只读；谁先写，谁才得到一份私有拷贝。</p><footer>—— 据 Rashid 等对 Mach 虚存的表述；Unix fork 语义在 Bach 与 MOS 中的整理</footer></div><p><a href="/cs/overcommit">上一课</a>让物理帧成为稀缺品。<a href="/cs/process-image">进程映像</a>的 fork 若立刻复制全部用户页，缺页与置换会被自己打爆，而子进程往往马上 <code>exec</code> 丢掉刚复制的空间。缺口是<strong>写时复制（COW）</strong>：共享只读，写时再拆。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>POSIX fork 语义是「子进程地址空间是父的副本」。副本可以是逻辑的：页表指向同一帧，两端页表项去掉写权限。写故障时内核判断是 COW 而非真保护错，分配新帧、拷贝、恢复写权限。缺口不是新的调页，而是把「复制」从 fork 时刻挪到第一次写。</p><p>本课不把 <code>vfork</code> 与 <code>clone</code> 的全部标志写完。</p><p><span class="marginnote">引用计数记有多少页表指向该帧。降到一且本应可写时，可直接恢复写权限，不必拷贝。</span></p><p><span class="marginnote">直觉类比：fork 像两个人合看同一份文件，只递一张「你们俩共用」的便条，不复印；谁要先拿笔改，才去复印一份自己留着改。COW 便条就是页表项里那个只读标记。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>fork：复制页表项，COW 位 + 只读，帧引用加一。任一方写入 → 缺页 → 若 COW 则拷贝；若引用已为一则只改权限。<code>exec</code> 拆掉旧映射，COW 页若仅剩另一进程，引用下降。与<a href="/cs/demand-paging">按需调页</a>叠：尚未触碰的文件页仍可双方共享同一文件映射，直到写。</p>',10)),(o(),l(A,null,{default:E(()=>[n(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FORK%5B%22fork%3A%20%E5%85%B1%E4%BA%AB%E5%8F%AA%E8%AF%BB%22%5D%20--%3E%20WRITE%5B%22%E5%86%99%E6%95%85%E9%9A%9C%22%5D%0A%20%20WRITE%20--%3E%20COPY%5B%22%E6%96%B0%E5%B8%A7%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20COPY%20--%3E%20PRIV%5B%22%E7%A7%81%E6%9C%89%E5%8F%AF%E5%86%99%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：父子两个页表指向同一物理帧时引用计数为 2；子进程写这一页触发故障，内核分配新帧拷贝内容，子进程页表改指新帧，父进程那侧的引用降回 1——从此各自一份，互不影响。真正被复制的只有这一页 4 KB，不是整个地址空间。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"COW 让「创建进程」与「占用两倍物理内存」解耦，调度可以很快跑子进程。管道课的亲缘进程因此便宜。内核必须区分：文本本就只读，写是 SIGSEGV；数据页的只读可能是 COW。这是缺页处理里的类型字段，不是新的 MMU 周期。",-1)),(o(),l(A,null,{default:E(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%BC%BA%E9%A1%B5%E5%A4%84%E7%90%86%E7%A8%8B%E5%BA%8F%E6%94%B6%E5%88%B0%E5%86%99%E6%95%85%E9%9A%9C%22%5D%20--%3E%20Q1%7B%22%E9%A1%B5%E6%98%AF%E6%9C%AC%E6%9D%A5%E5%B0%B1%E5%8F%AA%E8%AF%BB%E7%9A%84%E6%96%87%E6%9C%AC%E6%AE%B5%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20SEG%5B%22%E7%9C%9F%E4%BF%9D%E6%8A%A4%E9%94%99%3A%20%E5%8F%91%20SIGSEGV%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E9%A1%B5%E8%A1%A8%E9%A1%B9%E5%B8%A6%20COW%20%E6%A0%87%E8%AE%B0%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20SEG2%5B%22%E7%9C%9F%E4%BF%9D%E6%8A%A4%E9%94%99%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20Q3%7B%22%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%E4%B8%BA%E4%B8%80%3F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20FIX%5B%22%E7%9B%B4%E6%8E%A5%E6%81%A2%E5%A4%8D%E5%86%99%E6%9D%83%E9%99%90%2C%20%E9%9B%B6%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20DUP%5B%22%E5%88%86%E9%85%8D%E6%96%B0%E5%B8%A7%2C%20%E6%8B%B7%E8%B4%9D%2C%20%E5%90%84%E8%87%AA%E6%94%B9%E6%8C%87%E5%90%91%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：初学者容易以为「页被标成只读」就等于真的禁止写。实际上内核是故意借用 MMU 的只读保护位当「正在共享」的标签——写故障在这里不是错误，而是预期中的信号，用来触发拷贝。</span></p><p>置换仍可淘汰 COW 页：若干净且来自文件，丢掉即可；若匿名且仍共享，要小心写回与引用，实现复杂，主干只承认「共享页淘汰更挑剔」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入跨进程的 <code>userfaultfd</code> 等机制，不把容器快照的全部 COW 文件系统（如 overlay）混进进程页。也不讲硬件的两阶段缺页性能数字。安全课会关心是否漏恢复写位，本课假定实现正确。</p><p>KSM 等合并相同页是另一方向的共享，本课不把去重当 fork 语义。</p><p>内核在写故障路径上必须序列化引用计数，避免两份都以为自己该独占。</p><p>后课默认：fork 后页按写拆分。把文件直接接进地址空间、不一定走 <code>read</code> 拷贝，下一课 mmap。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fork 的副本语义可用共享只读 + 写时拷贝实现。</li><li>真保护错与 COW 故障要在缺页里分开。</li><li>文件映射进虚空间是 mmap 的缺口。</li><li>出处：Mach 虚存（Rashid et al.）；Bach, <em>The Design of the UNIX Operating System</em>；Tanenbaum <em>MOS</em>。</li></ul>',9))])}const _=i(p,[["render",c]]);export{u as __pageData,_ as default};
